{"new_str": "import re
from app.services import users


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_create_user(params: dict) -> tuple[int, dict]:
    name = params.get("name")
    email = params.get("email")

    if not isinstance(name, str) or not isinstance(email, str):
        return 400, {"error": "invalid user"}

    name = name.strip()
    if not (1 <= len(name) <= 50):
        return 400, {"error": "invalid user"}

    # Basic email regex for "plausible email address"
    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return 400, {"error": "invalid user"}

    if users.find_user_by_email(email):
        return 409, {"error": "email already exists"}

    user = users.create_user(name, email)
    return 201, user
